'use strict';
const el=document.querySelector('#game'),key='dbp-decisions-v2.1';let G,s;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(t,a)=>'<button class="btn" data-act="'+a+'">'+t+'</button>';
const fresh=()=>({id:G.entry,selected:null,log:[]});
function save(){try{localStorage.setItem(key,JSON.stringify(s))}catch{}}
function load(){try{const a=JSON.parse(localStorage.getItem(key));if(a&&Array.isArray(a.log)){const move={'02':'03','05':'06','E3':'03','E6':'06'};if(move[a.id]){a.id=move[a.id];a.selected=null}a.log=a.log.filter(([k,i])=>G.nodes[k]?.choices[i]);}if(a&&Array.isArray(a.log)&&(G.nodes[a.id]||G.endings[a.id])&&(a.selected===null||G.nodes[a.id]?.choices[a.selected]))return a}catch{}return null}
function show(v){el.innerHTML=v;const track=el.querySelector('.clock ol');if(track)track.scrollLeft=track.scrollWidth;window.scrollTo(0,0)}
function home(){const old=load();show('<section class="intro"><span class="tag">VIỆT NAM &nbsp; / &nbsp; 1954</span><h1>Điện Biên Phủ</h1><div class="introgrid"><div><h3>Một thung lũng gần biên giới Lào</h3><p>Năm 1954, cuộc chiến giữa quân Pháp và lực lượng kháng chiến Việt Nam đã kéo dài hơn bảy năm. Pháp muốn giữ quyền kiểm soát ở Đông Dương. Việt Minh chiến đấu để giành độc lập cho Việt Nam.</p><p>Tháng 11/1953, quân Pháp nhảy dù xuống <b>Điện Biên Phủ</b>, một thung lũng ở Tây Bắc Việt Nam, gần Lào. Họ xây các vị trí phòng thủ quanh sân bay <b>Mường Thanh</b> và nhận tiếp tế bằng máy bay. Phía Việt Minh quyết định mở chiến dịch đánh vào cụm cứ điểm này.</p></div><img src="boi-canh.svg" alt="Sơ đồ Tây Bắc Việt Nam: hướng sang Lào ở bên trái, Mường Thanh và sân bay trong lòng chảo, Huổi He ở ngoài lòng chảo."></div><section class="brief"><span class="tag">26 THÁNG 1 &nbsp; / &nbsp; HANG HUỔI HE</span><h3>Giờ ra quyết định</h3><p><b>Huổi He là hang đặt sở chỉ huy của Việt Minh lúc này.</b> Tại đây, Đại tướng Võ Nguyên Giáp phải quyết định: đánh ngay như đã định, hay hoãn lại khi quân Pháp đã củng cố phòng thủ?</p></section>'+btn(old?'Tiếp tục lượt chơi →':'Vào chiến dịch →',old?'resume':'start')+(old?' <button class="btn alt" data-act="restart">Chơi lại từ đầu</button>':'')+'</section>')}
function refs(ids){return '<details><summary>Nguồn đối chiếu ('+ids.length+')</summary><ul>'+ids.map(id=>{const v=G.sources[id];return '<li><a target="_blank" rel="noopener" href="'+esc(v.url)+'">'+esc(v.title)+'</a><div class="small">'+esc(v.loc)+'</div></li>'}).join('')+'</ul></details>'}
function history(){return s.log.length?'<details><summary>Những quyết định đã qua</summary><ol>'+s.log.map(([k,i],j)=>'<li>'+(j<(s.skip||0)?'<small>Đường dẫn tới cảnh</small> ':'')+esc(G.nodes[k].title)+' → '+esc(G.nodes[k].choices[i].action)+'</li>').join('')+'</ol></details>':''}
function timeline(){const end=!!G.endings[s.id],trail=s.log.map(([k])=>k);if(!end)trail.push(s.id);
const items=trail.map((k,i)=>{const n=G.nodes[k],active=!end&&i===trail.length-1;return '<li'+(active?' aria-current="step"':'')+'><small>'+esc(n.time.split(' · ')[0].replace('/1954',''))+'</small><b>'+esc(n.marker)+'</b></li>'});
if(end)items.push('<li aria-current="step"><small>Kết cục</small><b>Kết thúc lượt</b></li>');
return '<section class="clock" aria-label="Dòng thời gian chiến dịch"><div class="clockTitle">DÒNG THỜI GIAN <span>1954</span></div><ol>'+items.join('')+'</ol></section>'}
function render(){const n=G.nodes[s.id],e=G.endings[s.id];if(e){const origin=s.log.at(-1)?.[0],variant=e.by_origin?.[origin];show(timeline()+'<span class="tag">KẾT CỤC</span><h2>'+esc(variant?.[0]||e.title)+'</h2><p class="lede">'+esc(variant?.[1]||e.closing)+'</p><details><summary>Đối chiếu sử liệu</summary><p>'+esc(e.status==='Lịch sử'?'Diễn biến lịch sử.':'Kết cục phóng tác.')+' '+esc(e.compare_with_record)+'</p>'+refs(e.sources)+'</details>'+history()+btn('Chơi lại →','start'));return}
const c=n.choices[s.selected],head=timeline()+'<span class="tag">'+esc(n.time.split(' · ')[0].replace(/ ·?giả định/g,''))+' &nbsp; / &nbsp; '+esc(n.place)+'</span><h2>'+esc(n.title)+'</h2>';
if(c){show(head+'<section class="paper"><span class="tag">KẾT QUẢ</span><h3>'+esc(c.action)+'</h3><p class="lede">'+esc(c.after_choice)+'</p><p><b>Được:</b> '+esc(c.won)+'</p><p><b>Mất:</b> '+esc(c.lost)+'</p></section>'+btn(G.endings[c.next]?'Xem kết cục →':'Tiếp tục →','next')+'<details><summary>Đối chiếu sử liệu</summary><p>'+esc(c.evidence_status)+' · '+esc(n.after_only.historical_record)+'</p><a href="dien-bien-phu.html#'+encodeURIComponent(n.anchor)+'" target="_blank" rel="noopener">Hồ sơ chiến dịch ↗</a>'+refs(n.sources)+'</details>');return}
show(head+'<p class="lede">'+esc(n.before.situation)+'</p>'+(n.map?'<img src="ban-keo.svg" alt="Bản Kéo trong chiến trường Điện Biên Phủ" style="width:100%;max-width:420px;height:auto">':'')+'<section class="line"><h3>'+esc(n.before.question)+'</h3><div class="choices">'+n.choices.map((c,i)=>'<button class="pick" data-choice="'+i+'"><small>'+String.fromCharCode(65+i)+'</small><strong>'+esc(c.action)+'</strong></button>').join('')+'</div></section>'+history()+'<div class="line">'+btn('Trang đầu','home')+'</div>')}
el.onclick=ev=>{const b=ev.target.closest('button');if(!b)return;const a=b.dataset.act;if(a==='home'){home();return}if(a==='restart'&&!confirm('Bắt đầu lượt mới và thay tiến độ hiện tại?'))return;if(['start','restart'].includes(a))s=fresh();else if(a==='resume')s=load()||fresh();else if(b.dataset.choice!==undefined&&s.selected===null)s.selected=Number(b.dataset.choice);else if(a==='next'&&s.selected!==null){const i=s.selected,k=s.id;s.log.push([k,i]);s.id=G.nodes[k].choices[i].next;s.selected=null}else return;save();render()};
function openRoute(){if(!G)return;const h=location.hash;if(h==='#cay-nhanh'){show(treeView(G,load()));wireTree(G,el);return}if(h.startsWith('#quyet/')){const path=h.slice(7),target=routeState(G,path.slice(0,-1)),i=path.slice(-1).charCodeAt(0)-65;if(target&&G.nodes[target.id]?.choices[i]){s=target;s.selected=i;save();window.history.replaceState(null,'',location.pathname+location.search);render();return}}if(h.startsWith('#den/')){let code=h.slice(5);let target=routeState(G,code==='goc'?'':code);if(target){s=target;save();window.history.replaceState(null,'',location.pathname+location.search);render();return}}home()}
window.addEventListener('hashchange',openRoute);
fetch('dien-bien-phu.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{G=data;openRoute()}).catch(()=>el.textContent='Không tải được dữ liệu chiến dịch. Hãy tải lại trang.');
